/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic data,
    output logic start_shifting
);
    typedef enum logic [2:0] {
        SEARCH = 3'd0,
        PREFIX_1 = 3'd1,
        PREFIX_11 = 3'd2,
        PREFIX_110 = 3'd3,
        FOUND = 3'd4
    } state_t;
    state_t state_r, state_n;

    always_comb begin
        state_n = state_r;
        case (state_r)
            SEARCH:     if (data) state_n = PREFIX_1;
            PREFIX_1:   if (data) state_n = PREFIX_11;
                        else state_n = SEARCH;
            PREFIX_11:  if ("'!data) state_n = PREFIX_110;
            PREFIX_110: if (data) state_n = FOUND;
                        else state_n = SEARCH;
            FOUND:      state_n = FOUND;
            default:    state_n = SEARCH;
        endcase
    end

    always_ff @(posedge clk) begin
        if (reset)
            state_r <= SEARCH;
        else
            state_r <= state_n;
    end

    assign start_shifting = (state_r == FOUND);
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'"'EOF'
module dev_tb;
    logic clk = 0;
    logic reset = 0;
    logic data = 0;
    wire start_shifting;
    logic [3:0] history = 0;
    integer valid_count = 0;
    logic expected = 0;
    integer checks = 0;
    integer stream, bit_index;
    TopModule dut (.clk(clk), .reset(reset), .data(data), .start_shifting(start_shifting));
    always #5 clk = ~clk;

    task automatic step(input logic rst, input logic bit_value);
        @(negedge clk);
        reset = rst;
        data = bit_value;
        @(posedge clk);
        if (rst) begin
            history = 0;
            valid_count = 0;
            expected = 0;
        end else begin
            history = {history[2:0], bit_value};
            if (valid_count < 4) valid_count = valid_count + 1;
            if (valid_count == 4 && history == 4'b1101) expected = 1;
        end
        #1;
        checks = checks + 1;
        if (start_shifting "'!== expected)
            $fatal(1, "Mismatch check=%0d history=%b reset=%b expected=%b actual=%b", checks, history, rst, expected, start_shifting);
    endtask

    initial begin
        step(1, 1);
        for (stream = 0; stream < 4096; stream = stream + 1) begin
            step(1, 0);
            for (bit_index = 11; bit_index >= 0; bit_index = bit_index - 1)
                step(0, ((stream >> bit_index) & 1));
        end
        // Reset discards a partial prefix and ignores the simultaneous data bit.
        step(1, 0);
        step(0, 1); step(0, 1); step(0, 0);
        step(1, 1);
        step(0, 1); step(0, 0); step(0, 1);
        step(0, 1); step(0, 0); step(0, 1);
        // Found is absorbing, even for long unrelated input runs.
        repeat (32) step(0, 0);
        // Reset changes the output only at a positive clock edge.
        @(negedge clk);
        reset = 1;
        #1;
        if (start_shifting !== 1'"'b1) "'$fatal(1, "Reset acted asynchronously");
        @(posedge clk);
        #1;
        if (start_shifting !== 1'"'b0) "'$fatal(1, "Synchronous reset failed");
        history = 0; valid_count = 0; expected = 0;
        step(1, 1);
        step(0, 1); step(0, 1); step(0, 0); step(0, 1);
        $display("PASS: %0d oracle comparisons, exhaustive length-12 streams and reset/sticky checks", checks);
        $finish;
    end
    initial begin
        #1000000;
        $fatal(1, "Testbench watchdog timeout");
    end
endmodule
EOF
timeout 30s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > development_compile.log 2>&1
compile_rc=$?
cat development_compile.log
exit "$compile_rc"'

